  rvb_compare_col_verdict: { en:"Verdict", ko:"결과", zh:"结论" },
  rvb_compare_col_buyequity: { en:"Buy equity", ko:"구매 시 자산", zh:"购房权益" },
  rvb_compare_col_rentwealth: { en:"Rent wealth", ko:"임대 시 자산", zh:"租房财富" },
