  hci_lede: { en:"Estimate your annual house and contents insurance premium in NZ, based on sum insured, region and excess.",
    ko:"보장액, 지역, 자기부담금을 기준으로 뉴질랜드의 연간 주택 및 가재도구 보험료를 추정해보세요.",
    zh:"根据保额、地区和自付额,估算你在新西兰的房屋及财物保险年度保费。" },
  hci_label_homesum: { en:"Home rebuild sum insured", ko:"주택 재건축 보장액", zh:"房屋重建保额" },
