  ocr_fig_alt: { en:"Aerial view of the Auckland waterfront and CBD skyline, New Zealand", ko:"뉴질랜드 오클랜드 워터프론트와 시내 스카이라인 항공 사진", zh:"新西兰奥克兰海滨与市中心天际线航拍图" },
