  nzau_fig_alt: { en:"Rooftop solar panels on a house under a coastal sky", ko:"해안가 주택 지붕 위의 태양광 패널", zh:"海边天空下屋顶上的太阳能板" },
  nzau_fig_caption: { en:"Rooftop solar is a common sight across the Tasman — much less so here, so far.",
    ko:"지붕형 태양광은 호주에서는 흔한 풍경이지만, 아직 뉴질랜드에서는 그렇지 않습니다.",
    zh:"在澳大利亚,屋顶太阳能随处可见——但目前在新西兰还远没有那么普遍。" },

  nzau_h2_gap: { en:"The headline gap", ko:"가장 눈에 띄는 격차", zh:"最显著的差距" },
