  // ---------- Article: Real cost of owning a car ----------
  cco_breadcrumb: { en:"The real cost of owning a car", ko:"자동차 소유의 실제 비용", zh:"拥有一辆车的真实成本" },
  cco_eyebrow: { en:"Motoring · Explainer", ko:"자동차 · 설명", zh:"汽车 · 解读" },
  cco_h1: { en:"How much does it really cost to own a car in NZ?", ko:"뉴질랜드에서 자동차를 소유하면 실제로 얼마나 들까요?", zh:"在新西兰养车到底要花多少钱?" },
  cco_lede: { en:"The sticker price is just the start. Here's everything else a car actually costs to own in New Zealand — and how it adds up per week.",
    ko:"차량 가격표는 시작일 뿐입니다. 뉴질랜드에서 자동차를 소유하는 데 실제로 드는 모든 비용과 주당 얼마나 쌓이는지 알아봅니다.",
    zh:"车贴价格只是个开始。本文将解读在新西兰养车实际需要花费的所有成本,以及这些费用每周累积起来是多少。" },
  cco_byline_published: { en:"Published 22 July 2026", ko:"2026년 7월 22일 게시", zh:"发布于2026年7月22日" },
  cco_byline_updated: { en:"Updated 22 July 2026", ko:"2026년 7월 22일 업데이트", zh:"更新于2026年7月22日" },
