  hhs_lede: { en:"Wondering if your spending is normal? Here's how an average New Zealand household's monthly budget breaks down.",
    ko:"내 지출이 정상적인 수준인지 궁금하신가요? 평균적인 뉴질랜드 가구의 월간 예산이 어떻게 구성되는지 알아봅니다.",
    zh:"想知道你的支出是否正常吗?本文将解读一个典型新西兰家庭的月度预算构成。" },
  hhs_byline_published: { en:"Published 22 July 2026", ko:"2026년 7월 22일 게시", zh:"发布于2026年7月22日" },
  hhs_byline_updated: { en:"Updated 22 July 2026", ko:"2026년 7월 22일 업데이트", zh:"更新于2026年7月22日" },
  hhs_byline_readtime: { en:"6 min read", ko:"읽는 시간 6분", zh:"阅读需6分钟" },
  hhs_fig_alt: { en:"A person pushing a shopping cart full of groceries", ko:"식료품이 가득 담긴 쇼핑 카트를 미는 사람", zh:"一个人推着装满食品的购物车" },
  hhs_fig_caption: { en:"Groceries are usually the second-biggest line in a household budget, after housing.",
    ko:"식료품은 보통 주거비 다음으로 가구 예산에서 두 번째로 큰 항목입니다.", zh:"食品杂货通常是家庭预算中仅次于住房的第二大支出项目。" },
  hhs_h2_breakdown: { en:"The average household budget breakdown", ko:"평균 가구 예산 구성", zh:"平均家庭预算构成" },
  hhs_h2_overspend: { en:"Where most households overspend without realising", ko:"많은 가구가 모르게 초과 지출하는 부분", zh:"大多数家庭在不知不觉中超支的地方" },
  hhs_h2_compare: { en:"How your spending compares", ko:"내 지출과 비교해보기", zh:"你的支出与平均水平相比如何" },
