  hhs_stat_food_lbl: { en:"Food & groceries", ko:"식품 및 식료품", zh:"食品杂货" },
  hhs_stat_food_val: { en:"~15-20%", ko:"약 15~20%", zh:"约15-20%" },
  hhs_stat_transport_lbl: { en:"Transport", ko:"교통비", zh:"交通" },
  hhs_stat_transport_val: { en:"~10-15%", ko:"약 10~15%", zh:"约10-15%" },
  hhs_p_breakdown1: { en:"Housing — rent or mortgage repayments — is by far the biggest line in most NZ household budgets, commonly somewhere between 30-40% of take-home pay, and often more in Auckland or Wellington. Food, transport, utilities and insurance round out most of what's left.",
    ko:"주거비(임대료 또는 모기지 상환액)는 대부분의 뉴질랜드 가구 예산에서 단연 가장 큰 항목으로, 보통 실수령액의 30~40% 정도이며 오클랜드나 웰링턴에서는 더 높은 경우가 많습니다. 식품, 교통, 공과금, 보험이 나머지 대부분을 차지합니다.",
    zh:"住房支出(房租或房贷还款)是绝大多数新西兰家庭预算中最大的一项,通常占税后收入的30-40%左右,在奥克兰或惠灵顿往往更高。食品、交通、水电煤和保险则占据了剩余支出的大部分。" },
  hhs_p_breakdown2: { en:"After the big three (housing, food, transport), the remainder typically splits across utilities, insurance, healthcare, and discretionary spending like entertainment and eating out — the category that usually has the most room to flex.",
    ko:"3대 항목(주거, 식품, 교통) 이후 나머지는 보통 공과금, 보험, 의료비, 그리고 오락이나 외식 같은 재량 지출로 나뉘는데, 이 재량 지출 항목이 보통 조정 여지가 가장 큽니다.",
    zh:"在三大项(住房、食品、交通)之后,剩余支出通常分布在水电煤、保险、医疗保健,以及娱乐和外出就餐等可自由支配的支出上——而这类支出通常是最有调整空间的。" },
  hhs_table_col1: { en:"Category", ko:"항목", zh:"类别" },
  hhs_table_col2: { en:"Typical % of spend", ko:"일반적인 지출 비중", zh:"典型支出占比" },
